  "メトリクスは傾向、ログは事象、トレースはリクエストの経路を示します。": "메트릭은 경향, 로그는 사건, 트레이스는 요청의 경로를 보여 줍니다.",
  "`kubectl top pods` が `Metrics API not available` を返す。原因は？": "`kubectl top pods`가 `Metrics API not available`을 반환한다. 원인은?",
