  "望ましい状態を Git に置き、ツールが差分を検出して自動的にクラスタへ適用する": "바람직한 상태를 Git에 두고, 도구가 차이를 감지해 자동으로 클러스터에 적용한다",
  "CI サーバーから kubectl apply を直接実行する": "CI 서버에서 kubectl apply를 직접 실행한다",
