  "Prometheus のデータ取得方式は？": "Prometheus의 데이터 취득 방식은?",
  "対象の /metrics エンドポイントを定期的にスクレイプする（pull 型）": "대상의 /metrics 엔드포인트를 정기적으로 스크레이프한다(pull형)",
