  "サービスメッシュを導入する典型的な理由は？": "서비스 메시를 도입하는 전형적인 이유는?",
  "アプリのコードを変えずに mTLS・リトライ・トラフィック分割・詳細な計測を得られる": "앱 코드를 바꾸지 않고 mTLS·재시도·트래픽 분할·상세한 계측을 얻을 수 있다",
  "Pod の起動が速くなる": "Pod 시작이 빨라진다",
