  "ノード数を減らせる": "노드 수를 줄일 수 있다",
  "サイドカー（または ambient 構成）が通信を仲介します。複雑さの増加とのトレードオフです。": "사이드카(또는 ambient 구성)가 통신을 중개합니다. 복잡성 증가와의 트레이드오프입니다.",
  "OpenTelemetry の役割は？": "OpenTelemetry의 역할은?",
  "メトリクス・ログ・トレースの収集と送信を、ベンダー非依存の規格で統一する": "메트릭·로그·트레이스의 수집과 송신을 벤더에 의존하지 않는 규격으로 통일한다",
  "Kubernetes のスケジューラを置き換える": "Kubernetes 스케줄러를 대체한다",
