  "マニフェスト・クォータ・テンプレートでプロジェクトを管理できる": "매니페스트·쿼터·템플릿으로 프로젝트를 관리할 수 있다",
  "`oc create -f` / `oc apply -f` / `oc get -o yaml` / `oc patch` / `oc set` を使い、手作業を再現可能にする": "`oc create -f` / `oc apply -f` / `oc get -o yaml` / `oc patch` / `oc set`을 써서 수작업을 재현 가능하게 한다",
  "`oc new-project` を一般ユーザーに許可するのは self-provisioner ロール（外すと管理者のみが作成）": "`oc new-project`를 일반 사용자에게 허용하는 것은 self-provisioner 역할(빼면 관리자만 생성)",
  "Namespace ごとの上限は ResourceQuota と LimitRange。新規 Project の既定は Project テンプレートで設定": "Namespace별 상한은 ResourceQuota와 LimitRange. 새 Project의 기본값은 Project 템플릿으로 설정",
  "アプリの雛形は Template（`oc process -f tpl.yaml -p NAME=app | oc apply -f -`）": "앱의 틀은 Template(`oc process -f tpl.yaml -p NAME=app | oc apply -f -`)",
  "Operator は Subscription で導入（1 つの Namespace か全クラスタ）。`oc get csv` で導入済みを確認": "Operator는 Subscription으로 도입(하나의 Namespace 또는 클러스터 전체). `oc get csv`로 도입 완료를 확인",
  "一般ユーザーが自分でプロジェクトを作れないようにするには？": "일반 사용자가 스스로 프로젝트를 만들지 못하게 하려면?",
  "self-provisioner クラスタロールの割り当てを外す": "self-provisioner 클러스터 역할 할당을 뺀다",
  "すべてのユーザーを削除する": "모든 사용자를 삭제한다",
  "ResourceQuota を 0 にする": "ResourceQuota를 0으로 한다",
  "oc new-project コマンドを無効化する": "oc new-project 명령어를 비활성화한다",
  "`oc adm policy remove-cluster-role-from-group self-provisioner system:authenticated:oauth` のように外します。": "`oc adm policy remove-cluster-role-from-group self-provisioner system:authenticated:oauth`처럼 뺍니다.",
  "プロジェクト内で使えるメモリ・CPU・Pod 数の合計を制限するリソースは？": "프로젝트 안에서 쓸 수 있는 메모리·CPU·Pod 수의 합계를 제한하는 리소스는?",
  "コンテナ単位の既定値・上下限は LimitRange。両方を組み合わせるのが定番です。": "컨테이너 단위의 기본값·상하한은 LimitRange. 둘을 조합하는 것이 정석입니다.",
  "稼働中の Deployment のイメージを宣言的に差し替えるコマンドは？": "가동 중인 Deployment의 이미지를 선언적으로 교체하는 명령어는?",
  "`oc set env` `oc set resources` も同様に、マニフェストを部分的に更新します。": "`oc set env` `oc set resources`도 마찬가지로 매니페스트를 부분적으로 업데이트합니다.",
  "Operator が導入されているかを確認するコマンドは？": "Operator가 도입되어 있는지 확인하는 명령어는?",
  "oc get csv（ClusterServiceVersion）": "oc get csv(ClusterServiceVersion)",
  "OLM は Subscription → InstallPlan → CSV の流れで導入します。": "OLM은 Subscription → InstallPlan → CSV 흐름으로 도입합니다.",
  "ストレージとバックアップ（EX280 / EX370）": "스토리지와 백업(EX280 / EX370)",
  "永続ボリュームを与え、アプリをバックアップ・復元できる": "영속 볼륨을 주고, 앱을 백업·복원할 수 있다",
  "Kubernetes と同じ PVC / StorageClass。ODF（OpenShift Data Foundation）は内部モードで Ceph ベースのストレージを提供": "Kubernetes와 같은 PVC / StorageClass. ODF(OpenShift Data Foundation)는 내부 모드로 Ceph 기반 스토리지를 제공",
  "ODF が提供するのは RBD（ブロック・RWO）・CephFS（共有・RWX）・オブジェクト（RGW / NooBaa）": "ODF가 제공하는 것은 RBD(블록·RWO)·CephFS(공유·RWX)·오브젝트(RGW / NooBaa)",
  "`oc set volume deployment/app --add --claim-name=data --mount-path=/var/lib/data` でボリュームを追加": "`oc set volume deployment/app --add --claim-name=data --mount-path=/var/lib/data`로 볼륨을 추가",
  "バックアップは OADP（Velero ベース）: 対象 Namespace・保存先（S3 互換）・スケジュールを宣言する": "백업은 OADP(Velero 기반): 대상 Namespace·저장 위치(S3 호환)·스케줄을 선언한다",
  "復元前に Namespace の状態と PV の回収ポリシーを確認する": "복원 전에 Namespace 상태와 PV의 회수 정책을 확인한다",
  "複数の Pod（異なるノード）から同じボリュームに書き込みたい。ODF で選ぶのは？": "여러 Pod(다른 노드)에서 같은 볼륨에 쓰고 싶다. ODF에서 고르는 것은?",
  "CephFS ベースの共有ファイルストレージ（RWX）": "CephFS 기반 공유 파일 스토리지(RWX)",
  "RBD ベースのブロックストレージ（RWO）": "RBD 기반 블록 스토리지(RWO)",
  "オブジェクトストレージのみ": "오브젝트 스토리지만",
  "アクセスモード RWX に対応しているのは共有ファイルシステムです。": "액세스 모드 RWX를 지원하는 것은 공유 파일 시스템입니다.",
  "Deployment `app` に PVC `data` を /var/lib/data としてマウントするコマンドは？": "Deployment `app`에 PVC `data`를 /var/lib/data로 마운트하는 명령어는?",
  "マニフェストを直接編集してもよいですが、試験では `oc set volume` が速い定番です。": "매니페스트를 직접 편집해도 되지만, 시험에서는 `oc set volume`이 빠른 정석입니다.",
  "OpenShift でアプリとその永続データをバックアップする仕組みは？": "OpenShift에서 앱과 그 영속 데이터를 백업하는 구조는?",
  "OADP（OpenShift API for Data Protection、Velero ベース）": "OADP(OpenShift API for Data Protection, Velero 기반)",
  "etcd のスナップショットのみ": "etcd 스냅숏만",
  "oc get -o yaml の保存だけ": "oc get -o yaml 저장만",
  "etcd バックアップはクラスタ状態の保護で、アプリのデータは OADP で保護します。": "etcd 백업은 클러스터 상태의 보호이며, 앱 데이터는 OADP로 보호합니다.",
  "監視・ログ・GitOps・Pipelines（EX380 / EX288）": "모니터링·로그·GitOps·Pipelines(EX380 / EX288)",
  "クラスタの可観測性と継続的デリバリを構成できる": "클러스터의 관측 가능성과 지속적 전달을 구성할 수 있다",
  "ログは Logging Operator（収集 Vector → 保存 Loki）。`oc logs` は Pod 単体、横断検索はコンソールの Logs": "로그는 Logging Operator(수집 Vector → 저장 Loki). `oc logs`는 Pod 단독, 횡단 검색은 콘솔의 Logs",
  "監視はプラットフォーム用 Prometheus ＋ユーザーワークロード監視。警報は Alertmanager": "모니터링은 플랫폼용 Prometheus + 사용자 워크로드 모니터링. 경보는 Alertmanager",
  "GitOps（Argo CD）: Application リソースで Git のパスとクラスタを結び、差分を自動同期（selfHeal・prune）": "GitOps(Argo CD): Application 리소스로 Git 경로와 클러스터를 묶고, 차이를 자동 동기화(selfHeal·prune)",
  "Pipelines（Tekton）: Task / Pipeline / PipelineRun。ビルドからデプロイまでをクラスタ内で実行": "Pipelines(Tekton): Task / Pipeline / PipelineRun. 빌드부터 배포까지를 클러스터 안에서 실행",
